INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Datenbasis dasselbe wie eine Datenbank?', 2, '[{"text": "Ja", "correct": true, "because": "Synonyme Begriffe"}, {"text": "Nein", "correct": false, "because": "Beide bezeichnen Datensammlungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Datenbasis?', 3, '[{"text": "Daten strukturiert speichern", "correct": true, "because": "Zugriff und Analyse erleichtern"}, {"text": "Hardware reparieren", "correct": false, "because": "Kein Hardware-Fokus"}, {"text": "Netzwerk konfigurieren", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zu einer Datenbasis?', 5, '[{"text": "Tabellen", "correct": true, "because": "Speichern strukturierte Daten"}, {"text": "Datenbankmanagementsystem", "correct": true, "because": "Verwaltet Daten"}, {"text": "Grafiktreiber", "correct": false, "because": "Kein Datenbasis-Teil"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine Datenbasis kann relationale Daten speichern. b) Sie ist immer physisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Physisch nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung einer Datenbasis?', 4, '[{"text": "Datenintegrität", "correct": false, "because": "Sichert Konsistenz"}, {"text": "Abfragesprache", "correct": false, "because": "Zugriff erleichtert"}, {"text": "Bildschirmgröße", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Datenbasis immer strukturiert ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch unstrukturierte Daten möglich"}, {"text": "Ja", "correct": false, "because": "Verschiedene Typen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datenbasis ist für große Datenmengen geeignet?', 3, '[{"text": "NoSQL", "correct": true, "because": "Skalierbar für Big Data"}, {"text": "Textdatei", "correct": false, "because": "Unpraktisch"}, {"text": "Excel", "correct": false, "because": "Begrenzte Kapazität"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Datenbasis?', 5, '[{"text": "Schneller Zugriff", "correct": true, "because": "Daten organisiert"}, {"text": "Datenkonsistenz", "correct": true, "because": "Integrität gewährleistet"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Hardware-Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Eine Datenbasis speichert Informationen. b) Sie ist immer lokal. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Cloud möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Datenbasis?', 4, '[{"text": "Speichermedium", "correct": false, "because": "Datenablage nötig"}, {"text": "Verwaltungssystem", "correct": false, "because": "Organisiert Daten"}, {"text": "Küchenzeile", "correct": true, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine Datenbasis nur für Firmen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch privat nutzbar"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datenarten speichert eine Datenbasis?', 4, '[{"text": "Strukturierte", "correct": true, "because": "Tabellenform"}, {"text": "Unstrukturierte", "correct": true, "because": "z. B. Multimedia"}, {"text": "Physische", "correct": false, "because": "Kein Datentyp"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Datenbasis keine Sicherheit braucht. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Schutz essenziell"}, {"text": "Ja", "correct": false, "because": "Sicherheit nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer Datenbasis?', 3, '[{"text": "Zuverlässigkeit", "correct": true, "because": "Datenverfügbarkeit"}, {"text": "Schnelle Installation", "correct": false, "because": "Funktion wichtiger"}, {"text": "Minimale Kosten", "correct": false, "because": "Qualität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine Datenbasis kann Cloud-basiert sein. b) Sie ist immer unstrukturiert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Struktur variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen bietet eine Datenbasis?', 5, '[{"text": "Daten speichern", "correct": true, "because": "Grundfunktion"}, {"text": "Daten abrufen", "correct": true, "because": "Zugriff ermöglichen"}, {"text": "Grafiken rendern", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Datenbasis unwichtig?', 3, '[{"text": "Sicherheitsmaßnahmen", "correct": false, "because": "Schützt Daten"}, {"text": "Datenstruktur", "correct": false, "because": "Beeinflusst Verarbeitung"}, {"text": "Monitorauflösung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann eine Datenbasis ohne DBMS laufen?', 3, '[{"text": "Ja", "correct": true, "because": "Aber eingeschränkt"}, {"text": "Nein", "correct": false, "because": "DBMS oft nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Datenbasis immer groß ist?', 2, '[{"text": "Nein", "correct": true, "because": "Größe variabel"}, {"text": "Ja", "correct": false, "because": "Auch klein möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt das DBMS bei einer Datenbasis?', 4, '[{"text": "Verwaltung", "correct": true, "because": "Organisiert und sichert"}, {"text": "Netzwerksteuerung", "correct": false, "because": "Kein Netzwerkfokus"}, {"text": "Grafikverarbeitung", "correct": false, "because": "Irrelevant"}]');
